// Fit Finder scoring, ported 1:1 from the Income Fit Test workbook (Options sheet, columns AF-AZ).
const COUNTRIES = [["United States","US$",0.6928],["United Kingdom","£",0.5243],["Canada","C$",0.9891],["Australia","A$",1.0],["New Zealand","NZ$",1.2362],["Somewhere else (use US$)","US$",0.6928]];
const CONTACT = ["None","Messaging only","Phone or video calls","In person"];
const TECH = ["Low","Medium","High"];
function scoreAll(opts, a) {
  const c = COUNTRIES.find(x => x[0] === a.country) || COUNTRIES[0], fx = c[2];
  const hrs = +a.hours, blk = +a.block, bud = +a.budget, CN = CONTACT.indexOf(a.contact), TN = TECH.indexOf(a.tech) + 1;
  return opts.map(o => {
    const why = [];
    if (o.minh > hrs + 2) why.push(`needs about ${o.minh} hours a week and you have ${hrs}`);
    if (o.eve === "Partly" && a.evenings === "No") why.push("relies on evenings or weekends");
    if (o.cap * fx > bud) why.push("start-up above your budget");
    if (o.car === "Yes" && a.car === "No") why.push("needs a car");
    if (o.space === "Yes" && a.space === "No") why.push("needs space you don't have");
    if (o.checks === "Yes" && a.checks === "No") why.push("needs checks or registration");
    if (o.contact > CN + 1) why.push("needs more customer contact than you want");
    if (a.soon === "Yes" && o.weeks > 8) why.push("first income likely beyond 8 weeks");
    if (a.remote === "Yes" && o.remote === "No") why.push("needs in-person work");
    if (a.camera === "No" && o.camera === "Yes") why.push("needs you on camera");
    const AG = o.minh <= hrs ? 3 : o.minh <= hrs + 2 ? 1 : 0;
    const AH = o.block <= blk ? 3 : o.block <= blk + 1 ? 1 : 0;
    const AI = o.eve === "No" ? 3 : a.evenings === "Yes" ? 2 : 0;
    const AJ = o.contact <= CN ? 3 : o.contact === CN + 1 ? 1 : 0;
    const life = AG + AH + AI + AJ;
    const AL = (a.skill1 === o.tag1 || a.skill1 === o.tag2) ? 3 : ((a.skill2 && (a.skill2 === o.tag1 || a.skill2 === o.tag2)) ? 2 : (o.skill === 1 ? 2 : 0));
    const AM = bud === 0 ? (o.cap === 0 ? 3 : 0) : (o.cap * fx <= bud / 2 ? 3 : o.cap * fx <= bud ? 2 : 0);
    const AN = o.tech <= TN ? 3 : o.tech === TN + 1 ? 1 : 0;
    const ready = 2 * AL + AM + AN;
    const AT = a.soon === "Yes" ? (o.weeks <= 2 ? 3 : o.weeks <= 4 ? 2 : o.weeks <= 8 ? 1 : 0) : (o.weeks <= 4 ? 3 : o.weeks <= 8 ? 2 : o.weeks <= 16 ? 1 : 0);
    const comm = o.demand + o.lev + o.comp + AT;
    const total = life + ready + comm;
    const AW = a.priority === "Money soon" ? AT : a.priority === "Flexibility" ? AH : a.priority === "Building something over time" ? o.lev : 0;
    const filtered = why.length > 0;
    const key = filtered ? -1 : total + AW + comm / 100 + (99 - o.id) / 100000;
    const band = filtered ? "Filtered out" : total >= 27 ? "Strong fit" : total >= 21 ? "Good fit" : total >= 15 ? "Possible with changes" : "Weak fit";
    const crit = [[AG,"fits your weekly hours"],[AH,"fits your work blocks"],[AI,"no evenings needed"],[AJ,"matches your contact style"],[AL,"uses your skills"],[AM,"well inside your budget"],[AN,"comfortable tech load"],[o.demand,"strong demand evidence"],[o.lev,"income not capped by the hour"],[o.comp,"room in the market"],[AT,"quick to first income for your need"]];
    const weakNames = [[AG,"your weekly hours"],[AH,"your block length"],[AI,"evenings needed"],[AJ,"customer contact style"],[AL,"skills match"],[AM,"budget stretch"],[AN,"tech load"],[o.demand,"weak demand evidence"],[o.lev,"income capped by the hour"],[o.comp,"crowded market"],[AT,"slow to first income"]];
    const pref = ({Products: "Product", Services: "Service"}[a.psa] === o.psa ? 1 : 0) + (a.rp && a.rp !== "Either" && a.rp === o.rp ? 1 : 0);
    return { o, why, life, ready, comm, total, AW, key, pref, band, filtered,
      strengths: crit.filter(x => x[0] === 3).map(x => x[1]), weak: weakNames.filter(x => x[0] <= 1).map(x => x[1]),
      cap: Math.round(o.cap * fx / 10) * 10, sym: c[1] };
  });
}
function byFit(x, y) { return Math.floor(y.key) - Math.floor(x.key) || y.pref - x.pref || y.key - x.key; }
function top3(scored) { return scored.filter(s => !s.filtered && s.total >= 15).sort(byFit).slice(0, 3); }
function calcNums(c, H){
 const price = +c.price, hrs = +c.hrs, cost = +c.cost || 0, fixed = +c.fixed || 0, start = +c.start || 0, unpaid = c.unpaid === undefined || c.unpaid === "" ? 2 : +c.unpaid || 0, mH = H * 52 / 12, paid = Math.max(0, H - unpaid);
 if (!price || !hrs) return null;
 const margin = price - cost, cap = paid * 52 / 12 / hrs;
 const sc = [0.25, 0.5, 1].map(f => { const n = Math.floor(cap * f), p = n * margin - fixed; return {f, n, p, h: p / mH}; });
 return {margin, cap, paid, unpaid, sc, be: margin > 0 ? Math.ceil(start / margin) : null};
}
